    init_table
        .compute_root()
        .vectorize(j, vec_table)
        .parallel(i);

    init_seq.realize(seq);
    init_table.realize(table);
}

int main(int argc, char *argv[]) {
    // Problem size (from nussinov.hpp / PolyBench)
    int n = N;

    // Buffers:
    // seq[i]      -> seq(i)
    // table[i][j] -> table(j, i)  (C is row-major; Halide is column-major)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2> table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // ImageParams to expose the current state to Halide
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    // Scalar parameter: current “distance” d = j - i (diagonal index)
    Param<int> d_param("d");

    // Bind the buffers once; we mutate 'table' in-place on the host,
    // and Halide will always read the up-to-date values from it.
    seq_param.set(seq);
    table_param.set(table);

    // ------------------------------------------------------------------
    // Optimized per-diagonal DP update as a Halide pipeline
    //
    // Classic Nussinov DP:
    //
    // for (i = N-1; i >= 0; i--) {
    //   for (j = i+1; j < N; j++) {
    //     best = table[i][j];        // initially zero
    //     best = max(best, table[i][j-1]);
    //     best = max(best, table[i+1][j]);
    //     if (i < j-1)
    //         best = max(best, table[i+1][j-1] + match(seq[i], seq[j]));
    //     else
    //         best = max(best, table[i+1][j-1]);
    //     for (k = i+1; k < j; k++)
    //       best = max(best, table[i][k] + table[k+1][j]);
    //     table[i][j] = best;
    //   }
    // }
    //
    // Dependencies only go from shorter intervals (j-i smaller) to
    // longer intervals (j-i larger). So we can legally process the
    // table one diagonal at a time in *increasing* distance d = j-i:
    //
    //   for (d = 1; d < N; d++)
    //     for (i = 0; i < N-d; i++) {
    //       j = i + d;
    //       ... same recurrence ...
    //     }
    //
    // Within a fixed diagonal d, all (i,j) = (i, i+d) are independent
    // of each other, because they only depend on entries with
    // (j'-i') < d. This lets us compute one whole diagonal with a
    // single Halide call, vectorized and parallelized over i.
    // ------------------------------------------------------------------

    Var i("i");

    // Reduction over the split point k for a fixed diagonal d.
    // r.x will range from 1 .. d-1; we’ll remap to k = i + r.x.
    RDom r(1, d_param - 1, "r");

    Func cell_diag("cell_diag");

    {
        Expr i_e = i;
        Expr d_e = d_param;
        Expr j_e = i_e + d_e;  // j = i + d

        // Start from zero – initial table[i][j] is 0 in the original code.
        Expr best = cast<num_t>(0);

        // table[i][j-1] -> table_param(j-1, i)
        best = max(best, table_param(j_e - 1, i_e));

        // table[i+1][j] -> table_param(j, i+1)
        best = max(best, table_param(j_e, i_e + 1));

        // Diagonal / pairing term:
        //
        // If i < j-1:
        //   best = max(best, table[i+1][j-1] + match(seq[i], seq[j]));
        // else
        //   best = max(best, table[i+1][j-1]);
        //
        // match(b1,b2) = ((b1 + b2) == 3 ? 1 : 0)
        Expr b1 = cast<int32_t>(seq_param(i_e));
        Expr b2 = cast<int32_t>(seq_param(j_e));
        Expr match_val = select(b1 + b2 == 3, 1, 0);

        Expr can_pair = i_e < (j_e - 1);
        Expr match_term = select(can_pair,
                                 cast<num_t>(match_val),
                                 cast<num_t>(0));

        // table[i+1][j-1] -> table_param(j-1, i+1)
        Expr diag_candidate = table_param(j_e - 1, i_e + 1) + match_term;
        best = max(best, diag_candidate);

        // Initialize the pure definition of this diagonal cell.
        cell_diag(i) = best;

        // Split term:
        //
        // for (k = i+1; k < j; k++)
        //   best = max(best, table[i][k] + table[k+1][j]);
        //
        // We express this as a reduction in r.x with:
        //   k = i + r.x,  r.x in [1, d-1]
        Expr k = i_e + r.x;
        Expr split_candidate =
            table_param(k, i_e) +          // table[i][k]   -> table_param(k, i)
            table_param(j_e, k + 1);       // table[k+1][j] -> table_param(j, k+1)

        cell_diag(i) = max(cell_diag(i), split_candidate);
    }

    // ------------------------------------------------------------------
    // Schedule for the diagonal kernel
    //
    // We compute one full diagonal at a time.
    // Parallelize and vectorize across i (independent cells),
    // and run the reduction over r.x innermost.
    // ------------------------------------------------------------------
    {
        Target target = get_host_target();
        const int vec_width = natural_vector_size<num_t>(target);

        Var io("io"), ii("ii");

        // Pure step: cell_diag(i) = best(i)
        cell_diag
            .compute_root()
            // Tile i for better cache behavior on large N.
            .split(i, io, ii, 64)
            .vectorize(ii, vec_width)
            .parallel(io);

        // Reduction step over r.x, for each i.
        cell_diag.update()
            .split(i, io, ii, 64)
            .vectorize(ii, vec_width)
            .parallel(io);

        // JIT-compile once with the chosen target.
        cell_diag.compile_jit(target);
    }

    // Buffer to hold one diagonal at a time; we’ll crop it per distance.
    Halide::Buffer<num_t> diag_storage(n);

    // Time the DP kernel (all diagonals, plus Halide calls).
    auto start = std::chrono::high_resolution_clock::now();

    // Process diagonals in increasing distance d = j - i.
    // For each d, we compute all (i,j) with j = i + d.
    //
    // This order is a legal topological order for the DP, because
    // all dependencies of a cell (i,j) have strictly smaller j-i.
    for (int d = 1; d < n; ++d) {
        d_param.set(d);

        const int len = n - d;  // number of (i,j) pairs on this diagonal
        if (len <= 0) {
            continue;
        }

        // Crop a 1D view into diag_storage for the current diagonal.
        Halide::Buffer<num_t> diag = diag_storage.cropped(0, 0, len);

        // Compute the entire diagonal in one Halide call:
        // diag(i) = table[i][i+d]  (via the recurrence above)
        cell_diag.realize(diag);

        // Scatter the diagonal results back into the 2D DP table:
        // table[i][j] -> table(j, i) with j = i + d
        for (int i0 = 0; i0 < len; ++i0) {
            int j = i0 + d;
            int ii = i0;
            table(j, ii) = diag(i0);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the live-out data (upper triangle of the table),
    // similar to the PolyBench print_array() function.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        int t = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                if (t % 20 == 0) {
                    std::cerr << '\n';
                }
                std::cerr << table(j, i) << ' ';
                ++t;
            }
        }
        std::cerr << '\n';
    }

    // Print kernel execution time (in seconds, to 6 decimal places).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
