    init_array(n, seq, table);

    // ImageParams to expose the current state to Halide
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    // Scalar parameter: current subsequence length (j - i)
    Param<int> len_param("len");

    // Bind the buffers once; we mutate 'table' in-place on the host,
    // and Halide will always read the up-to-date values from it.
    seq_param.set(seq);
    table_param.set(table);

    // --------------------------------------------------------------------
    // Optimized per-diagonal DP kernel in Halide
    //
    // Classical Nussinov DP is usually expressed over subsequence
    // length L = j - i. For fixed L, all (i, j = i+L) on that diagonal
    // are independent given that shorter subsequences (smaller L) are
    // already computed. We exploit this by having Halide compute an
    // entire diagonal at once, instead of a single cell per call.
    //
    // For a given length 'len':
    //   i ranges from 0 to n-len-1
    //   j = i + len
