    //   else
    //     best = max(best, table[i+1][j-1]);
    //   for (k = i+1; k < j; k++)
    //     best = max(best, table[i][k] + table[k+1][j]);
    //
    // mapped to Halide indexing as table(j, i) etc.
    // --------------------------------------------------------------------

    Var idx("idx"); // this is 'i' along a diagonal
    Func diag("diag");

    // Express i, j, and len as Expr so we can re-use them cleanly.
    Expr i = idx;
    Expr len = len_param;
    Expr j = i + len;

    // Current value table[i][j]; table is zero-initialized, so this is
    // only non-zero if we ever pre-initialize, but we keep it for
    // semantic equivalence.
    Expr best = table_param(j, i);

    // table[i][j-1]
    best = max(best, table_param(j - 1, i));

    // table[i+1][j]
    best = max(best, table_param(j, i + 1));

