    // match(b1, b2) = ((b1 + b2) == 3 ? 1 : 0), with bases in 0..3.
    Expr b1 = cast<int32_t>(seq_param(i));
    Expr b2 = cast<int32_t>(seq_param(j));
    Expr match_val = select(b1 + b2 == 3, 1, 0);

    // Only allow bonding when i < j-1; otherwise, do not add match().
    Expr match_term = select(i < j - 1,
                             cast<num_t>(match_val),
                             cast<num_t>(0));

    // table[i+1][j-1] + match_term
    Expr diag_candidate = table_param(j - 1, i + 1) + match_term;
    best = max(best, diag_candidate);

    // Split term over k = i+1..j-1. We re-parameterize k = i + r, where
    // r in [1, len-1]. This is an associative reduction in r for each i.
    Expr split_extent = len - 1; // when len == 1 this is 0; empty reduction
    RDom r(1, split_extent, "r");

    // pure definition: starting value for this diagonal cell
    diag(idx) = best;

    // reduction definition: for each r (and thus each k), maximize diag(idx)
    // with table[i][k] + table[k+1][j].
    //
    // k = i + r.x
    Expr k = i + r.x;
    Expr split_candidate = table_param(k, i) + table_param(j, k + 1);
    diag(idx) = max(diag(idx), split_candidate);

    // --------------------------------------------------------------------
    // Schedule for the diagonal kernel
    //
    // - compute_root: compute an entire diagonal as one stage.
    // - split + parallel: parallelize over tiles of 'idx'.
    // - vectorize: inner loop uses SIMD across multiple 'idx'.
    //
    // Constants below can be tuned for a given machine.
    // --------------------------------------------------------------------
    const int VEC_WIDTH = 8;   // reasonable default for 32-bit values on AVX2
    const int TILE_SIZE = 64;  // tile size in 'idx' for parallel work chunks

    Var tile("tile"), vec("vec");

    diag.compute_root()
        .split(idx, tile, vec, TILE_SIZE)
        .parallel(tile)
        .vectorize(vec, VEC_WIDTH);

    // Apply a similar schedule to the reduction update step.
    diag.update()
        .split(idx, tile, vec, TILE_SIZE)
        .parallel(tile)
        .vectorize(vec, VEC_WIDTH);

    // JIT-compile the per-diagonal pipeline once.
    diag.compile_jit();

    // --------------------------------------------------------------------
    // Run the dynamic program, measuring only the DP kernel time.
    //
    // We sweep diagonals in increasing subsequence length (len = 1..n-1).
    // For each len, Halide computes all cells (i, j=i+len) into a 1D
    // buffer 'diag_buf', then we copy those values back into 'table'.
    //
    // This order is topologically valid for the Nussinov recurrence:
    // every dependency of table[i][j] lies on a strictly shorter
    // subsequence (i.e. smaller len), so all required values have been
    // fixed when we process diagonal 'len'. The final table is identical
    // to the original i-descending/j-ascending order.
    // --------------------------------------------------------------------

    // Reusable buffer to hold a diagonal; we crop it per length.
    Halide::Buffer<num_t> diag_buf(n);

    auto start = std::chrono::high_resolution_clock::now();

    // len = j - i, from 1 up to n-1
