        // Bind current subsequence length.
        len_param.set(len);

        // Realize just the first 'diag_len' entries of diag_buf.
        Halide::Buffer<num_t> diag_slice = diag_buf.cropped(0, 0, diag_len);
        diag.realize(diag_slice);

        // Write the diagonal back into the DP table.
        //
        // C:    table[i][j]
        // Here: table(j, i)
        for (int i_host = 0; i_host < diag_len; ++i_host) {
            int j_host = i_host + len;
            table(j_host, i_host) = diag_slice(i_host);
