#include <chrono>
#include <iomanip>
#include <iostream>
#include <cstdint>

#include "Halide.h"

// include common definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (e.g. N, DATA_TYPE)
#include "nussinov.hpp"

using num_t  = DATA_TYPE;   // type used for table entries
using base_t = uint8_t;     // type used for RNA bases (0..3)

using namespace Halide;

/**
 * Initialize seq and table as in the original C code.
 *
 *  - seq[i]        = (i+1) % 4   (bases encoded as 0..3)
 *  - table[i][j]   = 0           for all i,j
 *
 * Note: in C, table is indexed as table[i][j] in row-major order.
 *       We store it as Halide::Buffer with layout table(j, i) so that
 *       the inner-most loop (over j) writes contiguous memory.
 */
static void init_array(int n,
                       Halide::Buffer<base_t, 1> seq,
                       Halide::Buffer<num_t, 2> table) {
    Var i("i"), j("j");

    Func init_seq("init_seq"), init_table("init_table");

    // base is AGCT/0..3
    init_seq(i) = cast<base_t>((i + 1) % 4);

    // table[i][j] = 0 for all i,j
    // Remember: C uses table[i][j]; we map that to table(j, i).
    init_table(j, i) = cast<num_t>(0);

    // Simple but reasonably efficient schedules for the initialization:
    //  - vectorize seq initialization (it's a single contiguous array)
    //  - parallelize rows of the table and vectorize across columns
    init_seq.compute_root()
            .vectorize(i, 32);

    init_table.compute_root()
              .parallel(i)
              .vectorize(j, 32);

    init_seq.realize(seq);
    init_table.realize(table);
}

int main(int argc, char *argv[]) {
    // Problem size (from nussinov.hpp / PolyBench)
    int n = N;

    // Buffers:
    //   seq[i]        -> seq(i)
    //   table[i][j]   -> table(j, i)  (C is row-major; Halide is column-major)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2> table(n, n);

    // Initialize input sequence and DP table
    init_array(n, seq, table);

    // ImageParams to expose the current state to Halide.
    // We mutate 'table' in-place on the host; Halide will always read
    // the up-to-date values from it because ImageParam just wraps the
    // underlying Buffer.
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    seq_param.set(seq);
    table_param.set(table);

    // Scalar parameter for the current diagonal offset d = j - i.
    // We will compute one full anti-diagonal of the DP table at a time.
    Param<int> diag_param("diag_param");

    // Define a Func that computes table[i][j] for all i on a fixed
    // diagonal j - i == diag_param, given the current contents of
    // 'table' and 'seq'.
    //
    // This expresses a *single-diagonal* update as a pure Halide
    // pipeline. We then drive the diagonal loop from C++ in the same
    // order as a standard wavefront Nussinov implementation.
    //
    // For a given diagonal d and row index i, we set j = i + d and
    // compute the same recurrence as the original C code:
    //
    //   table[i][j] = max(table[i][j],
    //                     table[i][j-1],
    //                     table[i+1][j],
    //                     table[i+1][j-1] + match(seq[i], seq[j]),
    //                     max_{k = i+1..j-1} (table[i][k] + table[k+1][j]))
    //
    // with match(b1,b2) = ((b1 + b2) == 3 ? 1 : 0) on bases 0..3.
    //
    // Dependencies:
    //   - table[i][j-1] and table[i+1][j] lie on diagonal d-1
    //   - table[i+1][j-1] lies on diagonal d-2 or below-diagonal
    //   - table[i][k] and table[k+1][j] lie on diagonals < d
    //
    // so all data dependencies for diagonal d are on earlier diagonals.
    // This means all cells on the same diagonal are independent of
    // each other, and can safely be computed together in one Halide
    // realization.
    Func cell("cell");
    Var i_var("i_var");

    {
        Expr i = i_var;
        Expr d = diag_param;
        Expr j = i + d;  // column index

        // Current value table[i][j]
        // (C: table[i][j] -> Halide: table_param(j, i))
        Expr best = table_param(j, i);

        // table[i][j] = max(table[i][j], table[i][j-1]);
        // For our loop order, j >= i+1 >= 1 always holds, so j-1 is in-bounds.
        best = max(best, table_param(j - 1, i));

        // table[i][j] = max(table[i][j], table[i+1][j]);
        // For all i for which a diagonal cell exists, we have i <= N-2,
        // so i+1 is always a valid row.
        best = max(best, table_param(j, i + 1));

        // Diagonal / pairing term:
        //
        // In the original C:
        //
        //   if (j-1 >= 0 && i+1 < N) {
        //     if (i < j-1)
        //       table[i][j] = max(table[i][j],
        //                          table[i+1][j-1] + match(seq[i], seq[j]));
        //     else
        //       table[i][j] = max(table[i][j], table[i+1][j-1]);
        //   }
        //
        // The outer condition is always true for the (i,j) pairs we
        // visit, so we only need to preserve the (i < j-1) branch.
        Expr b1 = cast<int32_t>(seq_param(i));
        Expr b2 = cast<int32_t>(seq_param(j));
        // match(b1,b2) = 1 iff (b1 + b2 == 3), else 0
        Expr can_pair = (i < j - 1) && (b1 + b2 == 3);

        // table[i+1][j-1] -> table_param(j-1, i+1)
        Expr diag_base = table_param(j - 1, i + 1);
        // If can_pair, add 1; otherwise just propagate diag_base.
        Expr diag_candidate = select(can_pair,
                                     diag_base + cast<num_t>(1),
                                     diag_base);
        best = max(best, diag_candidate);

        // Split term:
        //
        //   for (k = i+1; k < j; k++)
        //     table[i][j] = max(table[i][j], table[i][k] + table[k+1][j]);
        //
        // For a fixed diagonal d = j-i, this is a reduction over
        // k in [i+1, j-1], whose length is exactly d-1. We express
        // this as a reduction in k over cell(i).
        //
        // We use an RDom whose min and extent depend on the pure
        // variable i and the parameter diag_param. For diagonal d,
        // k runs from i+1 to i + d - 1 inclusive.
        Expr extent = max(diag_param - 1, 0);  // safe even for d=1 (extent = 0)
        RDom r(i + 1, extent, "r");

        // Pure definition: start from the best value excluding split term.
        cell(i_var) = best;

        // Reduction update: take the maximum over k.
        //
        // table[i][k]        -> table_param(k, i)
        // table[k+1][j]      -> table_param(j, k+1)
        cell(i_var) = max(cell(i_var),
                          table_param(r.x, i) + table_param(j, r.x + 1));
    }

    // JIT-compile the per-diagonal pipeline once. We use the host
    // target so Halide can pick an appropriate vector width.
    Target target = get_host_target();
    cell.compile_jit(target);

    // Pre-allocate a 1D buffer large enough to hold any diagonal.
    // The d-th diagonal (d = j-i) has length (n - d) for d >= 1.
    Halide::Buffer<num_t> diag_buffer(n);

    // Time the DP kernel (the diagonal loop plus Halide calls).
    auto start = std::chrono::high_resolution_clock::now();

    // Original kernel order (PolyBench):
    //
    //   for (i = N-1; i >= 0; i--) {
    //     for (j = i+1; j < N; j++) {
    //       ... updates to table[i][j] ...
    //     }
    //   }
    //
    // This is equivalent to a *wavefront* formulation that iterates
    // over increasing anti-diagonals d = j - i:
    //
    //   for (d = 1; d < N; d++) {
    //     for (i = 0; i < N-d; i++) {
    //       j = i + d;
    //       ... updates to table[i][j] ...
    //     }
    //   }
    //
    // For each (i,j), all dependencies are on strictly smaller
    // diagonals (or on the untouched below-diagonal region which
    // remains zero), so computing the diagonals in increasing d
    // order produces identical final results for integer DATA_TYPE.
    //
    // We exploit this property to compute an entire diagonal in a
    // single Halide realization, which substantially reduces the
    // per-call JIT/runtime overhead compared to computing one cell
    // at a time.
    for (int d = 1; d < n; ++d) {
        const int len = n - d;  // number of (i,j) pairs on this diagonal

        diag_param.set(d);

        // Create a lightweight view over the first 'len' elements of
        // diag_buffer. This avoids allocating a new Buffer each time,
        // while still giving Halide the correct extent for this call.
        Halide::Buffer<num_t> diag_slice = diag_buffer.cropped(0, 0, len);

        // Compute all table[i][i+d] values for i in [0, len-1].
        cell.realize(diag_slice);

        // Write the results back into our DP table.
        // Recall: C table[i][j] -> Halide table(j, i).
        for (int i = 0; i < len; ++i) {
            int j = i + d;
            table(j, i) = diag_slice(i);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the live-out data (upper triangle of the table),
    // similar to the PolyBench print_array() function.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        int t = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                if (t % 20 == 0) {
                    std::cerr << '\n';
                }
                std::cerr << table(j, i) << ' ';
                ++t;
            }
        }
        std::cerr << '\n';
    }

    // Print kernel execution time (in seconds, to 6 decimal places).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
