    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2> table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // ImageParams to expose the current state to Halide
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    // We will compute one full DP anti-diagonal at a time.
    // len_param = j - i for all cells on the current anti-diagonal.
    Param<int> len_param("len_param");

    // Bind the buffers once; we mutate 'table' in-place on the host,
    // and Halide will always read the up-to-date values from it.
    seq_param.set(seq);
    table_param.set(table);

    // ------------------------------------------------------------------
    // Halide pipeline for a *whole* anti-diagonal
    //
    // For a fixed length L = len_param, all cells with j - i == L
    // (i.e. (i, j) = (0, L), (1, L+1), ..., (n-L-1, n-1)) can be
    // computed independently: every dependency of table[i][j] is on
    // entries with strictly smaller interval length j'-i' < L.
    //
    // So we define a 1D Func cell_diag(ii) that returns the updated
    // value for table[i][j] with:
    //   i = ii
    //   j = ii + len_param
    //
    // and we run this Func once per anti-diagonal, then copy the
    // results back into the table buffer.
    // ------------------------------------------------------------------
    Var ii("ii");
    Func cell_diag("cell_diag");

    // Decode (i, j) from the anti-diagonal index and length.
    Expr i = ii;
    Expr len = len_param;
    Expr j = i + len;

    // Current value table[i][j]
    // (C: table[i][j] -> Halide: table_param(j, i))
    Expr best = table_param(j, i);

    // if (j-1 >= 0) table[i][j] = max(table[i][j], table[i][j-1]);
    // On any valid DP cell we always have j >= i+1 >= 1, so j-1 >= 0.
    best = max(best, table_param(j - 1, i));

    // if (i+1 < N) table[i][j] = max(table[i][j], table[i+1][j]);
    // For any (i,j) with j-i == len >= 1 we have i <= N-2, so i+1 < N.
    best = max(best, table_param(j, i + 1));

    // Diagonal / pairing term:
    //
    // if (j-1 >= 0 && i+1 < N) {
    //   if (i < j-1)
    //     table[i][j] = max(table[i][j],
    //                        table[i+1][j-1] + match(seq[i], seq[j]));
    //   else
    //     table[i][j] = max(table[i][j], table[i+1][j-1]);
    // }
    //
    // As above, the outer bounds check is always true for valid cells.
    // For i < j-1, we add match(seq[i],seq[j]); for i == j-1 (len=1)
    // we just use table[i+1][j-1].
    Expr b1 = cast<int32_t>(seq_param(i));
    Expr b2 = cast<int32_t>(seq_param(j));
    // match(b1,b2) = ((b1 + b2) == 3 ? 1 : 0)
    Expr match_val = select(b1 + b2 == 3, 1, 0);

    // When len == 1 (j == i+1) we should NOT add the match bonus.
    // For len > 1 we add match_val.
    Expr match_term = select(len > 1,
                             cast<num_t>(match_val),
                             cast<num_t>(0));

    // table[i+1][j-1] -> table_param(j-1, i+1)
    Expr diag_candidate = table_param(j - 1, i + 1) + match_term;
    best = max(best, diag_candidate);

    // Split term:
    //
    // for (k = i+1; k < j; k++)
    //   table[i][j] = max(table[i][j], table[i][k] + table[k+1][j]);
    //
    // For a fixed length len = j-i, we can parametrize k as:
    //   k = i + r, where r runs from 1 to len-1.
    //
    // We express this as a reduction over r.x in [1, len-1].
    // Note that len is a scalar Param, so the RDom bounds are uniform
    // across the entire realization of cell_diag.
    RDom r(1, len - 1, "r");
    Expr k = i + r.x;

    // Pure definition: initialize from 'best'.
    cell_diag(ii) = best;

    // Reduction update: take the maximum over all valid splits k.
    cell_diag(ii) = max(cell_diag(ii),
                        table_param(k, i) + table_param(j, k + 1));

    // JIT-compile the anti-diagonal pipeline once. We keep the default
    // schedule for the reduction; the major performance gain comes
    // from computing O(n) cells per call instead of a single cell.
    Target target = get_jit_target_from_environment();
    cell_diag.compile_jit(target);

    // ------------------------------------------------------------------
    // Host-side DP driver
    // ------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // We now iterate over anti-diagonals of increasing length:
    //
    // for (len = 1; len < N; len++) {
    //   for (i = 0; i+len < N; i++) {
    //     j = i + len;
    //     ... compute table[i][j] ...
    //   }
    // }
    //
    // For each length we:
    //   1. set len_param
    //   2. realize cell_diag over ii = 0 .. (n-len)-1 into a 1D buffer
