    Func init_seq("init_seq"), init_table("init_table");

    // base is AGCT/0..3
    init_seq(i) = cast<base_t>((i + 1) % 4);

    // table[i][j] = 0 for all i,j
    // Remember: C uses table[i][j]; we map that to table(j, i).
    init_table(j, i) = cast<num_t>(0);

    // Simple but decent schedule: vectorize over the fast-varying x
    // dimension and parallelize over the outer dimension for the
    // (potentially large) 2D table. This is a one‑time init cost,
    // but it's essentially free to optimize.
    Target t = get_host_target();
    const int vec_seq   = t.natural_vector_size(type_of<base_t>());
    const int vec_table = t.natural_vector_size(type_of<num_t>());

    init_seq
        .compute_root()
        .vectorize(i, vec_seq);

    init_table
        .compute_root()
        .parallel(j)
        .vectorize(i, vec_table);

    init_seq.realize(seq);
    init_table.realize(table);
}

int main(int argc, char *argv[]) {
    // Problem size (from nussinov.hpp / PolyBench)
    int n = N;

    // Buffers:
    // seq[i]      -> seq(i)
    // table[i][j] -> table(j, i)  (C is row-major; Halide is column-major)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2> table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // ImageParams to expose the current state to Halide
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    // Scalar parameter for the current diagonal distance d = j - i
    Param<int> d_param("d_param");

    // Bind the buffers once; we mutate 'table' in-place on the host,
    // and Halide will always read the up-to-date values from it.
    seq_param.set(seq);
    table_param.set(table);

    // ------------------------------------------------------------------
    // Optimized per-diagonal Halide kernel
    //
    // Original C kernel:
    //
    //   for (i = N-1; i >= 0; i--) {
    //     for (j = i+1; j < N; j++) {
    //       best = table[i][j];
    //       best = max(best, table[i][j-1]);
    //       best = max(best, table[i+1][j]);
    //       if (i < j-1)
    //         best = max(best, table[i+1][j-1] + match(seq[i],seq[j]));
    //       else
    //         best = max(best, table[i+1][j-1]);
    //       for (k = i+1; k < j; k++)
    //         best = max(best, table[i][k] + table[k+1][j]);
    //       table[i][j] = best;
    //     }
    //   }
    //
    // Dependency structure:
    //   Every dependency of cell (i,j) goes to cells with strictly
    //   smaller diagonal distance d' = (col-row) than d = j-i:
    //     - table[i][j-1]   : (i, j-1) has d-1
    //     - table[i+1][j]   : (i+1, j) has d-1
    //     - table[i+1][j-1] : (i+1, j-1) has d-2
    //     - table[i][k]     : (i, k) has k-i < j-i = d
    //     - table[k+1][j]   : (k+1, j) has j-(k+1) <= d-1
    //
    //   Thus, if we compute the DP in order of increasing diagonal
    //   distance d = 1..N-1, all required table entries already
    //   exist when we compute diagonal d, and there are *no*
    //   dependencies within a fixed d. This allows us to:
    //
    //     - Compute an entire diagonal d at once inside a single
    //       Halide realization (i.e., a 1-D Func over i).
    //     - Parallelize that 1-D loop over i, since cells along
    //       the same diagonal are independent.
    //
    //   This preserves the mathematical result of the original DP,
    //   but greatly reduces per-call overhead compared to calling
    //   a scalar Halide pipeline for each (i,j).
    // ------------------------------------------------------------------

    Func cell("cell");
    Var i_var("i");

    {
        // Logical coordinates for this diagonal:
        //   i in [0, n - d_param - 1]
        //   j = i + d_param
        Expr i = i_var;
        Expr j = i + d_param;

        // Current best value: table[i][j]
        // (C: table[i][j] -> Halide: table_param(j, i))
        Expr best = table_param(j, i);

        // Max with table[i][j-1]  (same row, previous column)
        best = max(best, table_param(j - 1, i));

        // Max with table[i+1][j]  (next row, same column)
        best = max(best, table_param(j, i + 1));

        // Diagonal / pairing term:
        //
        // Original:
        //   if (j-1 >= 0 && i+1 < N) {
        //     if (i < j-1)
        //       best = max(best, table[i+1][j-1] + match(seq[i], seq[j]));
        //     else
        //       best = max(best, table[i+1][j-1]);
        //   }
        //
        // In our diagonal traversal, j >= i+1 and 0 <= i <= N-2 for
        // all active cells, so the outer bounds checks are always true.
        //
        // match(seq[i], seq[j]) = ((seq[i] + seq[j]) == 3 ? 1 : 0)
        Expr b1 = cast<int32_t>(seq_param(i));
        Expr b2 = cast<int32_t>(seq_param(j));
        Expr match_val = select(b1 + b2 == 3, 1, 0);

        // Only allow bonding when i < j-1; otherwise, don't add match().
        Expr match_term = select(i < j - 1,
                                 cast<num_t>(match_val),
                                 cast<num_t>(0));

        // table[i+1][j-1] -> table_param(j-1, i+1)
        Expr diag_candidate = table_param(j - 1, i + 1) + match_term;
        best = max(best, diag_candidate);

        // Split term:
        //
        //   for (k = i+1; k < j; k++)
        //     best = max(best, table[i][k] + table[k+1][j]);
        //
        // We treat this as a reduction over k for each fixed (i,j).
        // RDom r.x in [i+1, j-1]  -> min = i+1, extent = j-i-1.
        Expr extent = j - i - 1;      // = d_param - 1 >= 0 for d_param >= 1
        RDom r(i + 1, extent, "r");

        // Pure definition: initialization with the non-split terms.
        cell(i_var) = best;

        // Reduction update: take the maximum over k.
        cell(i_var) = max(cell(i_var),
                          table_param(r.x, i) + table_param(j, r.x + 1));
    }

    // ------------------------------------------------------------------
    // Schedule for the diagonal kernel
    //
    // We compute an entire diagonal d in one call:
    //   - The loop over i_var is parallelizable (independent cells).
    //   - We also vectorize along i_var for better cache and SIMD use.
    // ------------------------------------------------------------------
    {
        Target t = get_host_target();
        const int vec_width = t.natural_vector_size(type_of<num_t>());

        cell
            .compute_root()
            .vectorize(i_var, vec_width)
            .parallel(i_var);

        cell.compile_jit(t);
    }

    // ------------------------------------------------------------------
    // Host-controlled DP traversal over diagonals
    // ------------------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // We reuse a single piece of storage for all diagonals by wrapping
    // it in a Halide::Buffer with varying extents. This avoids repeated
    // heap allocations inside Halide while keeping peak extra memory
    // to O(n) (one diagonal), well within the requested 50% limit
    // relative to the n x n DP table.
    std::vector<num_t> diag_storage(static_cast<size_t>(n));

    // Diagonals d = j - i, from 1 to n-1.
    for (int d = 1; d < n; ++d) {
        const int width = n - d;  // number of (i,j) pairs with j=i+d

        d_param.set(d);

        // Wrap the reusable storage in a 1-D Halide buffer of length 'width'.
        Halide::Buffer<num_t, 1> diag_buf(diag_storage.data(), width);

        // Compute all cells on diagonal d in one shot.
        //
        // For each i in [0, width-1], this produces table[i][j] for
        // j = i + d, using only table entries on earlier diagonals
        // (d' < d), which are already finalized.
        cell.realize(diag_buf);

        // Write back into the DP table. Recall:
        //   C: table[i][j]
        //   Halide: table(j, i)
        for (int i = 0; i < width; ++i) {
            int j = i + d;
            table(j, i) = diag_buf(i);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the live-out data (upper triangle of the table),
    // similar to the PolyBench print_array() function.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        int t = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                if (t % 20 == 0) {
                    std::cerr << '\n';
                }
                std::cerr << table(j, i) << ' ';
                ++t;
            }
        }
        std::cerr << '\n';
    }

    // Print kernel execution time (in seconds, to 6 decimal places).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
